import React, { useState } from 'react';

const Footer = () => {
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const handleSubscribe = (e) => {
    e.preventDefault();
    if (email) {
      setSubscribed(true);
      setEmail('');
      setTimeout(() => setSubscribed(false), 3000);
    }
  };

  // ✅ Функции навигации - добавляем только это
  const handleNavigation = (page) => {
    // Меняем hash в URL
    window.location.http = page;
  };

  const handleSectionNavigation = (section) => {
    // Для секций на главной странице
    window.location.htt = `home#${section}`;
  };

  return (
    <footer className="bg-gray-900 text-white">
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          {/* Brand */}
          <div>
            <h3 className="text-xl font-serif font-bold mb-4">LUNA AUREA</h3>
            <p className="text-gray-400">Уникальные украшения ручной работы</p>
          </div>

          {/* Menu */}
          <div>
            <h4 className="font-semibold mb-4">МЕНЮ</h4>
            <ul className="space-y-2">
              <li>
                <button 
                  onClick={() => handleNavigation('catalog')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  Коллекции
                </button>
              </li>
              <li>
                <button 
                  onClick={() => handleNavigation('catalog')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  Каталог
                </button>
              </li>
              <li>
                <button 
                  onClick={() => handleNavigation('home')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  О нас
                </button>
              </li>
            </ul>
          </div>

          {/* Help */}
          <div>
            <h4 className="font-semibold mb-4">ПОМОЩЬ</h4>
            <ul className="space-y-2">
              <li>
                <button 
                  onClick={() => handleSectionNavigation('delivery')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  Доставка
                </button>
              </li>
              <li>
                <button 
                  onClick={() => handleSectionNavigation('payment')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  Оплата
                </button>
              </li>
              <li>
                <button 
                  onClick={() => handleSectionNavigation('contacts')}
                  className="text-gray-400 hover:text-white transition-colors text-left"
                >
                  Контакты
                </button>
              </li>
            </ul>
          </div>

          {/* Subscription */}
          <div>
            <h4 className="font-semibold mb-4">ПОДПИСКА</h4>
            <p className="text-gray-400 mb-4">Будьте в курсе новинок</p>
            <form onSubmit={handleSubscribe} className="flex">
              <input
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="px-3 py-2 bg-gray-800 text-white rounded-l focus:outline-none focus:ring-2 focus:ring-gold-500 flex-grow"
                required
              />
              <button
                type="submit"
                className="bg-gold-600 hover:bg-gold-700 px-4 py-2 rounded-r transition-colors"
              >
                ✓
              </button>
            </form>
            {subscribed && (
              <div className="mt-2 p-2 bg-green-600 rounded text-sm transition-opacity">
                Спасибо за подписку!
              </div>
            )}
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
